/**
 * OnSite service worker. Deliberately hand-written rather than generated by
 * a plugin: the caching rule that actually matters here is narrow and easy
 * to get wrong silently. Never cache an API response (it is per-user and
 * often carries a bearer token in a header the cache API cannot key on); only
 * cache static files so the app still opens with something useful offline.
 * See docs/05-system-architecture.md's PWA notes.
 *
 * Same behaviour as the Next.js app's worker (apps/web/public/sw.js), with two
 * differences: the offline fallback is the static /offline.html (the SPA has no
 * server to render /offline), and the cache name is new, so activating this
 * worker also clears the old app's cache when the two share an origin.
 */

const CACHE_NAME = 'onsite-shell-owl-v1';
const OFFLINE_URL = '/offline.html';
const SHELL_ASSETS = [OFFLINE_URL, '/icon-192.png', '/manifest.webmanifest'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE_NAME)
      .then((cache) => cache.addAll(SHELL_ASSETS))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  // Never intercept API or realtime calls: those are per-user, often
  // authenticated, and must always reflect live server state.
  if (url.pathname.startsWith('/api/') || url.pathname.startsWith('/socket.io/')) return;
  // The licence list is regenerated by every build under the same name, so a
  // cached copy would go stale after a dependency upgrade.
  if (url.pathname === '/licenses.json' || url.pathname.startsWith('/licenses/')) return;

  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request).catch(() => caches.match(OFFLINE_URL).then((cached) => cached ?? Response.error())),
    );
    return;
  }

  event.respondWith(
    caches.match(request).then(
      (cached) =>
        cached ??
        fetch(request)
          .then((response) => {
            if (response.ok) {
              const copy = response.clone();
              caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));
            }
            return response;
          })
          .catch(() => cached ?? Response.error()),
    ),
  );
});

self.addEventListener('push', (event) => {
  if (!event.data) return;
  let payload;
  try {
    payload = event.data.json();
  } catch {
    payload = { title: 'OnSite', body: event.data.text() };
  }

  event.waitUntil(
    self.registration.showNotification(payload.title ?? 'OnSite', {
      body: payload.body,
      icon: '/icon-192.png',
      badge: '/icon-192.png',
      data: { url: payload.url ?? '/dashboard' },
    }),
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetUrl = event.notification.data?.url ?? '/dashboard';

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clients) => {
      const existing = clients.find((client) => new URL(client.url).pathname === targetUrl);
      if (existing) return existing.focus();
      return self.clients.openWindow(targetUrl);
    }),
  );
});
